"use strict";(self.webpackChunkeleven_plus_core_concepts=self.webpackChunkeleven_plus_core_concepts||[]).push([[3277],{3277:e=>{e.exports=JSON.parse('{"concept":"Think of a Number Problems","subject":"mathematics","category":"Algebra in Disguise","explanation":"These problems hide algebra behind \'I think of a number\' language. Convert to algebra: \'I think of a number\' = x. \'Double it\' = 2x. \'Add 5\' = 2x + 5. Work backwards from the final answer, or set up an equation. These are really linear equations in disguise!","examples":[{"question":"I think of a number, double it, then subtract 7. My answer is 19. What was my number?","solution":"13","explanation":"Let the number be x. Double it: 2x. Subtract 7: 2x - 7 = 19. Solve: 2x = 19 + 7 = 26, so x = 13. Check: double 13 = 26, subtract 7 = 19 \u2713"},{"question":"Stuart thinks of a number, adds 8, then divides by 3. His result is 12. What number did Stuart think of?","solution":"28","explanation":"Let Stuart\'s number be x. Add 8: x + 8. Divide by 3: (x + 8)/3 = 12. Multiply both sides by 3: x + 8 = 36. So x = 28. Check: 28 + 8 = 36, 36 \xf7 3 = 12 \u2713"},{"question":"I think of a number, multiply by 4, subtract twice the original number. My result is 18. Find my number.","solution":"9","explanation":"Let the number be x. Multiply by 4: 4x. Subtract twice the original: 4x - 2x = 2x. So 2x = 18, therefore x = 9. Check: multiply 9 by 4 = 36, subtract twice 9 (18) = 36 - 18 = 18 \u2713"}],"exercises":[{"type":"multiple-choice","question":"I think of a number, add 12, then halve the result. My answer is 15. What was my original number?","options":["6","9","15","18"],"correct":[3],"explanation":"Let x be the number. Add 12: x + 12. Halve: (x + 12)/2 = 15. Multiply by 2: x + 12 = 30. So x = 18."},{"type":"multiple-choice","question":"Maya thinks of a number, subtracts 5, then triples the result to get 24. What was her number?","options":["8","11","13","17"],"correct":[2],"explanation":"Let x be Maya\'s number. Subtract 5: x - 5. Triple: 3(x - 5) = 24. So x - 5 = 8, therefore x = 13."},{"type":"open-ended","question":"Ben thinks of a number, doubles it, adds 7, then divides by 3. His answer is 9. Set up an equation to find Ben\'s number.","sample_answer":"Let Ben\'s number be x. Then (2x + 7)/3 = 9. Solving: 2x + 7 = 27, so 2x = 20, therefore x = 10.","explanation":"Convert each step into algebra, then solve the equation."}],"tips":["Let the unknown number = x","Convert each operation into algebra step by step","Work backwards: reverse each operation","Always check your answer in the original problem","These are just linear equations with words!"]}')}}]);